using System.Linq;
using System.Linq.Dynamic;

public static class EnumerableExtensions
{
    public static IQueryable<T> OrderBy<T>(this IEnumerable<T> source, string orderBy)
    {
        return source.AsQueryable().OrderBy(orderBy);
    }
}
```
You can then use this extension method on any `IEnumerable<T>` collection, just like you would use the `OrderBy()` method on a `IQueryable<T>` collection.

For example:
```csharp
