  let max = -Infinity;
  arr.forEach(item => {
    if (typeof item === "number" && item > max) {
      max = item;
    }
  });
  return max;
}

console.log(findGreatestValue([2, 4, 8, 10, 15, "A", -5]));
```

**Input constraints:**

* Array must contain no more than 1000 elements.

