Here's the revised function:

```javascript
function findGreatestValue(arr) {
  // Check if the array length exceeds the limit of 1000 elements
  if (arr.length > 1000) {
    throw new Error("Array exceeds the maximum allowed length of 1000 elements.");
  }

  let max = -Infinity;
  let numericValueFound = false; // Flag to track if at least one numeric value is found

  arr.forEach(item => {
    if (typeof item === "number") {
      numericValueFound = true;
      if (item > max) {
        max = item;
      }
    }
  });

  // If no numeric value was found, return a specific value or message
  if (!numericValueFound) {
    return "No valid numeric value found in the array.";
  }

  return max;
}

