how would you express this in c++?
from typing import Dict, List, Tuple, Union

class BankAccount():
    def __init__(self, id):
        self.id = id
        self.balance = 0
        self.history = []

class Transaction():
    def __init__(self, account_id, operation, value):
        self.account_id = account_id
        self.operation = operation
        self.value = value

def account_transcations_with_undo(accounts_transactions: List[Tuple[int, str, int]]) -> Union[bool, str, List[int]]:
    accounts: Dict[int, BankAccount] = {}
    for i, (account_id, operation, value) in enumerate(accounts_transactions):
        # Initialize account if does not exist
        account = accounts.get(account_id)
        if not account:
            account = BankAccount(account_id)
            accounts[account_id] = account

        transaction = Transaction(account_id, operation, value)

        # Check negative deposit and excessive withdrawal
        if operation == 'Deposit':
            if value < 0:
                return f'Negative deposit at transaction index: {i}'
            else:
                account.balance += value
        elif operation == 'Withdrawal':
            if value > account.balance:
                return f'Exceeding withdrawal: {value} at transaction index: {i}. Available balance: {account.balance}'
            else:
                account.balance -= value

        account.history.append(transaction)

    # Check negative balance
    for account in accounts.values():
        if account.balance < 0:
            return f'Negative balance in account id: {account.id}'
    return 'All transactions are successful.'

# Test
print(account_transcations_with_undo([(1, 'Deposit', 1), (2, 'Deposit', 2), (1, 'Deposit', 3), (2, 'Withdrawal', 4)]))
print(account_transcations_with_undo([(1, 'Deposit', 5), (1, 'Withdrawal', 6), (1, 'Deposit', 1), (1, 'Withdrawal', 2)]))
print(account_transcations_with_undo([(3, 'Deposit', -10), (4, 'Deposit', -5)]))

