```c
#include <stdio.h>
#include <stdlib.h>
#include <libpq-fe.h>

PGconn *connect_to_redshift(const char *user, const char *password, const char *host, const char *port, const char *dbname) {
    PGconn *conn;
    char conninfo[200];
    sprintf(conninfo, "dbname=%s user=%s password=%s host=%s port=%s", dbname, user, password, host, port);
    conn = PQconnectdb(conninfo);

    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        exit(1);
    }

    return conn;
}

PGresult *perform_sql_operations(PGconn *conn, const char *sql_query) {
    PGresult *res;
    res = PQexec(conn, sql_query);

    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Query execution failed: %s", PQerrorMessage(conn));
        PQclear(res);
        exit(1);
    }

    return res;
}

int main() {
    const char *user = "<YOUR_AWS_ACCESS_KEY_ID>";
    const char *password = "<YOUR_AWS_SECRET_ACCESS_KEY>";
    const char *host = "<redshift-cluster-name>.redshift.amazonaws.com";
    const char *port = "5439";
    const char *dbname = "<Your_DB_Name>";

    PGconn *conn = connect_to_redshift(user, password, host, port, dbname);

    // Perform your SQL operations
    const char *sql_query = "SELECT * FROM your_table";
    PGresult *result = perform_sql_operations(conn, sql_query);

    // Print the results
    int rows = PQntuples(result);
    int cols = PQnfields(result);
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%s\t", PQgetvalue(result, i, j));
        }
        printf("\n");
    }

    // Close the connection
    PQclear(result);
    PQfinish(conn);

    return 0;
}
```

