```JavaScript
var http = require('http');
var data = JSON.stringify({
    "email": "new.email@example.com"
});

var options = {
    host: 'example.com',
    path: '/path/to/api',
    method: 'PUT',
    headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(data)
    }
};

http.request(options, function(res) {
    res.setEncoding('utf8');
    res.on('data', function (chunk) {
        console.log('BODY: ' + chunk);
    });
    res.on('end', function() {
        console.log('No more data in response.')
    });
}).write(data);
```

Your task is to:
1. Identify the errors in the code.
2. Correct them.
3. Finally, enhance the original task to include error handling in the code. Make sure your solution considers and properly handles potential server side errors (like 500 Internal Server Error) as well as client side errors (like 404 Not Found, 403 Forbidden). 

