use std::collections::HashMap;

fn float_common(floats: Vec<&str>) -> i32 {
    let mut counters = HashMap::new();

    // Iterate over each float represented as a string
    for float_str in floats.iter() {
        // Iterate over each character in the string
        for char in float_str.chars() {
            // Skip the decimal point
            if char != '.' {
                // Increment the count for this character in the map
                *counters.entry(char).or_insert(0) += 1;
            }
        }
    }

    // Find the maximum frequency
    let max_frequency = counters.values().cloned().max().unwrap_or(0);

    // Collect the characters that have the maximum frequency
    let most_common_chars: Vec<char> = counters.into_iter()
        .filter(|&(_, v)| v == max_frequency)
        .map(|(k, _)| k)
        .collect();

    // Sort the characters and return the first one converted to an integer
    let mut most_common_chars_sorted = most_common_chars;
    most_common_chars_sorted.sort_unstable();

    most_common_chars_sorted[0].to_digit(10).unwrap() as i32
}

fn main() {
    let floats = vec!["1.23", "2.34", "3.45", "4.56"];
    println!("Most common character: {}", float_common(floats));
}
```

