instruction:
i want to write unittest for javascript version of the following code:
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
bool move_one_ball(vector<int> arr){

    // If array is empty, return true.
    if(arr.empty()) return true; 

    int n = arr.size();
    vector<int> sortedArr(arr);

    // Sort the array in non-decreasing order
    sort(sortedArr.begin(), sortedArr.end());

    // Start from each index and try to match sorted array through right shift
    for(int startIdx = 0; startIdx < n; startIdx++){
        bool flag = true;
        for(int i = 0; i < n; i++){
            // Consider current index + startIdx as index for sortedArr
            if(arr[i] != sortedArr[(startIdx + i) % n]){
                flag = false;  // Mark flag false if any element does not match
                break;
            }
        }
        // If flag is still true, means arr can be sorted using shift operation
        if(flag) return true; 
    }
    return false;
}

// Testing the function
int main() {
    cout << boolalpha; // print bool as true or false
    cout << move_one_ball({3, 4, 5, 1, 2}) << "\n";  // true
    cout << move_one_ball({3, 5, 4, 1, 2}) << "\n";  // false
    cout << move_one_ball({-3, -4, -2, -1}) << "\n"; // false
    cout << move_one_ball({-1, -1, -1, -1}) << "\n"; // true
    cout << move_one_ball({}) << "\n";               // true
    return 0;
}

